V load(String key, Supplier<V> loader) {
    CompletableFuture<V> mine = new CompletableFuture<>();
    CompletableFuture<V> running = flights.putIfAbsent(key, mine);   // atomic: exactly one caller gets null
    if (running != null) {
        try { return running.join(); }
        catch (CompletionException e) { throw e.getCause() instanceof RuntimeException r ? r : e; }
    }
    try {
        V value = loader.get();
        mine.complete(value);
        return value;
    } catch (RuntimeException e) {
        mine.completeExceptionally(e);
        throw e;
    } finally {
        flights.remove(key, mine);                                    // not a cache: the next miss loads again
    }
}

